function isMaterializedCustomContent(value) {
  if (!value || typeof value !== "object" || Array.isArray(value)) return false;
  const record = (
    /** @type {Record<string, unknown>} */
    value
  );
  return record.isCustom === true || record.custom === true || record.source === "custom" || typeof record.customDefinitionId === "string" || typeof record.customDefinitionCategory === "string";
}
function nativeSemanticName(value) {
  if (isMaterializedCustomContent(value)) return "";
  if (typeof value === "string") return value;
  if (!value || typeof value !== "object" || Array.isArray(value)) return "";
  return String(
    /** @type {Record<string, unknown>} */
    value.name || ""
  );
}

